import {
	AfterViewInit,
	ChangeDetectionStrategy,
	Component,
	ElementRef,
	QueryList,
	ViewChildren,
	inject,
	Inject,
	effect,
	PLATFORM_ID,
} from '@angular/core';


import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';

@Component({
	selector: 'app-brand-audit',
	imports: [TranslateModule],
	templateUrl: './brand-audit.component.html',
	styleUrl: './brand-audit.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BrandAuditComponent implements AfterViewInit {
	@ViewChildren('revealText')
	revealTexts!: QueryList<ElementRef<HTMLElement>>;


		constructor(
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId: Object,
    public translationService: TranslationService,
  ) {
    effect(() => {
      const locale = this.translationService.currentLang() === 'ar' ? 'ar' : 'en';
    });
  }
	async ngAfterViewInit(): Promise<void> {
		// SSR protection
		if (!isPlatformBrowser(this.platformId)) {
			return;
		}

		gsap.registerPlugin(ScrollTrigger);

		// Load SplitText only in browser
		const { SplitText } = await import('gsap/SplitText');

		gsap.registerPlugin(SplitText);

		this.revealTexts.forEach((textElement) => {
			const element = textElement.nativeElement;

			const split = new SplitText(element, {
				type: 'words',
				aria: 'none',
			});

			// Initial state
			gsap.set(split.words, {
				opacity: 0.1,
			});

			// Reveal on scroll
			gsap.to(split.words, {
				opacity: 1,
				stagger: 0.05,
				ease: 'none',

				scrollTrigger: {
					trigger: element,
					start: 'top 80%',
					end: 'bottom 45%',
					scrub: 1,
				},
			});
		});
	}
}
