import { CommonModule, isPlatformBrowser } from '@angular/common';
import {
	AfterViewInit,
	ChangeDetectionStrategy,
	ChangeDetectorRef,
	Component,
	ElementRef,
	Inject,
	Input,
	NgZone,
	OnDestroy,
	PLATFORM_ID,
	QueryList,
	Renderer2,
	ViewChild,
	ViewChildren,
	computed,
	signal,
} from '@angular/core';
import { RouterModule } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';

export interface ServiceScrollerItem {
	number: string;
	key: string;
	image: string;
	alt?: string;
	title: string;
	dial?: string;
	description: string;
	price?: string;
	duration?: string;
	tags?: string[];
	cta?: string;
	link: string;
}
@Component({
	selector: 'app-services-scroller',
	standalone: true,
	imports: [CommonModule, RouterModule],
	templateUrl: './services-scroller.component.html',
	styleUrl: './services-scroller.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ServicesScrollerComponent implements AfterViewInit, OnDestroy {
	@Input() angleStep = 28;
	services: ServiceScrollerItem[] = [];
	@Input() scrollDistance = 1;
	@Input() scrubEase = 0.08;
	private readonly imageMinScale = 0.85;
	private readonly contentMinScale = 0.94;
	// Fraction of the unit scroll distance (on each side of an image's center
	// point) that stays fully in focus before the crossfade to the neighbor begins.
	private readonly imagePlateau = 0.35;
	// Desktop-only: how far (vh) a content block slides per unit of index
	// distance from the active item — viewport-relative rather than relative
	// to the (much smaller) content box, so a neighbor one index away sits a
	// full screen height off the top/bottom and travels the whole viewport
	// as it eases through translateY(0) on its way to/from active.
	private readonly contentSlideDistance = 100;
	private static readonly CONTENT_SLIDE_BREAKPOINT = '(min-width: 992px)';

	@ViewChild('pinPanel') private pinPanelRef?: ElementRef<HTMLDivElement>;
	@ViewChild('dial') private dialRef?: ElementRef<HTMLDivElement>;
	@ViewChildren('numberItem') private numberItems?: QueryList<ElementRef<HTMLDivElement>>;
	@ViewChildren('mobileNumberItem') private mobileNumberItems?: QueryList<
		ElementRef<HTMLSpanElement>
	>;
	@ViewChildren('contentItem') private contentItemRefs?: QueryList<ElementRef<HTMLDivElement>>;
	@ViewChildren('imageItem') private imageItemRefs?: QueryList<ElementRef<HTMLImageElement>>;

	readonly activeIndex = signal(0);
	readonly activeService = computed<ServiceScrollerItem | undefined>(
		() => this.services[this.activeIndex()],
	);

	private readonly isBrowser: boolean;
	private intersectionObserver?: IntersectionObserver;
	private ticking = false;
	private rafId?: number;
	private smoothedProgress = 0;
	private isDesktopContent = true;
	private contentSlideQuery?: MediaQueryList;
	private readonly onContentSlideQueryChange = (event: MediaQueryListEvent): void => {
		this.isDesktopContent = event.matches;
	};
	// Radius/spacing of the mobile dial's number arc (see `.services-mobile-dial`).
	private readonly mobileDialRadius = 300;
	private readonly mobileDialAngleStep = 30;

	private readonly serviceConfig = [
		{
			key: 'BRANDING',
			number: '01',
			image: '/images/new-images/scrollers/branding.png',
			alt: 'Branding and Rebranding',
			link: '/services/branding',
		},
		{
			key: 'BRAND_GUARDIAN',
			number: '02',
			image: '/images/new-images/scrollers/graphics.webp',
			alt: 'Brand Guardian',
			link: '/services/graphics',
		},
		{
			key: 'CUSTOM_WEBSITES',
			number: '03',
			image: '/images/new-images/scrollers/website.webp',
			alt: 'Custom Websites',
			link: '/services/website-development',
		},
		{
			key: 'ECOMMERCE',
			number: '04',
			image: '/images/new-images/scrollers/ecommerce.webp',
			alt: 'eCommerce Website Development',
			link: '/services/ecommerce-web-development',
		},
		{
			key: 'MAINTENANCE',
			number: '05',
			image: '/images/new-images/scrollers/studio.png',
			alt: 'Website Maintenance and Support',
			link: '/services/website-maintenance',
		},
	];
	constructor(
		private readonly hostRef: ElementRef<HTMLElement>,
		private readonly renderer: Renderer2,
		private readonly translate: TranslateService,
		private readonly cdr: ChangeDetectorRef,
		private readonly ngZone: NgZone,
		public readonly translationService: TranslationService,
		@Inject(PLATFORM_ID) platformId: Object,
	) {
		this.isBrowser = isPlatformBrowser(platformId);
	}
	private loadServices(): void {
		this.translate.stream('SCROLLMENU.SERVICES').subscribe((translations: any) => {
			this.services = this.serviceConfig.map((config) => {
				const service = translations?.[config.key];

				return {
					...config,
					title: service?.TITLE ?? '',
					dial: service?.DIAL ?? '',
					description: service?.DESCRIPTION ?? '',
					price: service?.PRICE ?? '',
					duration: service?.DURATION ?? '',
					tags: Array.isArray(service?.TAGS) ? service.TAGS : [],
					cta: service?.CTA ?? '',
				};
			});

			this.activeIndex.set(0);

			this.cdr.markForCheck();

			requestAnimationFrame(() => {
				this.applyScrollProgress();
			});
		});
	}

	ngAfterViewInit(): void {
		if (!this.isBrowser) {
			return;
		}

		this.loadServices();

		this.contentSlideQuery = window.matchMedia(ServicesScrollerComponent.CONTENT_SLIDE_BREAKPOINT);
		this.isDesktopContent = this.contentSlideQuery.matches;
		this.contentSlideQuery.addEventListener('change', this.onContentSlideQueryChange);

		// The animation loop only needs to run while the section is actually
		// on (or near) screen. Everything it drives — pin position, dial
		// rotation, content stack, image parallax — is computed straight off
		// live layout each frame, so there's nothing to resync on resize.
		this.ngZone.runOutsideAngular(() => {
			this.intersectionObserver = new IntersectionObserver(
				([entry]) => this.setTicking(entry.isIntersecting),
				{ rootMargin: '200px 0px' },
			);
			this.intersectionObserver.observe(this.hostRef.nativeElement);
		});

		this.applyScrollProgress();
	}
	ngOnDestroy(): void {
		if (!this.isBrowser) {
			return;
		}

		this.setTicking(false);
		this.intersectionObserver?.disconnect();
		this.contentSlideQuery?.removeEventListener('change', this.onContentSlideQueryChange);
	}

	private setTicking(active: boolean): void {
		if (active === this.ticking) {
			return;
		}

		this.ticking = active;

		if (!active) {
			if (this.rafId !== undefined) {
				cancelAnimationFrame(this.rafId);
				this.rafId = undefined;
			}

			return;
		}

		const step = () => {
			if (!this.ticking) {
				return;
			}

			this.applyScrollProgress();
			this.rafId = requestAnimationFrame(step);
		};

		this.rafId = requestAnimationFrame(step);
	}

	// Emulates GSAP ScrollTrigger's `pin: true` with plain JS: the panel stays
	// `position: fixed` while the tall host section scrolls past it, then
	// settles to `position: absolute` at the host's bottom edge once the
	// section is fully scrolled through. CSS `position: sticky` can't be used
	// here — this site's global `body { overflow-x: hidden }` makes `body` a
	// scroll container, which becomes the containing block for sticky
	// descendants instead of the viewport, so sticky never engages.
	private applyScrollProgress(): void {
		if (this.services.length === 0) {
			return;
		}

		const host = this.hostRef.nativeElement;
		const panel = this.pinPanelRef?.nativeElement;
		const viewportHeight = window.innerHeight;
		const scrollable = host.offsetHeight - viewportHeight;

		if (scrollable <= 0) {
			return;
		}

		const rect = host.getBoundingClientRect();

		if (panel) {
			if (rect.top > 0) {
				this.renderer.setStyle(panel, 'position', 'relative');
				this.renderer.removeStyle(panel, 'top');
				this.renderer.removeStyle(panel, 'left');
				this.renderer.removeStyle(panel, 'right');
				this.renderer.removeStyle(panel, 'width');
			} else if (rect.bottom <= viewportHeight) {
				this.renderer.setStyle(panel, 'position', 'absolute');
				this.renderer.setStyle(panel, 'top', `${scrollable}px`);
				this.renderer.setStyle(panel, 'left', '0px');
				this.renderer.setStyle(panel, 'width', '100%');
			} else {
				this.renderer.setStyle(panel, 'position', 'fixed');
				this.renderer.setStyle(panel, 'top', '0px');
				this.renderer.setStyle(panel, 'left', `${rect.left}px`);
				this.renderer.setStyle(panel, 'width', `${rect.width}px`);
			}
		}

		// The pin above stays glued exactly to the real scroll position. Everything
		// animated below, though, tracks an eased version of it — this is what
		// turns raw scroll deltas into fluid, inertial motion (equivalent to
		// GSAP's `scrub`) instead of the animation jumping in lockstep with every
		// wheel/trackpad tick.
		const targetProgress = clamp(-rect.top / scrollable, 0, 1);

		if (Math.abs(targetProgress - this.smoothedProgress) < 0.0005) {
			this.smoothedProgress = targetProgress;
		} else {
			this.smoothedProgress += (targetProgress - this.smoothedProgress) * this.scrubEase;
		}

		const progress = this.smoothedProgress;
		const rawIndex = progress * (this.services.length - 1);
		const index = Math.round(rawIndex);

		const isRtl = document.documentElement.dir === 'rtl';

		const rotation = -rawIndex * this.angleStep;

		// Dial rotation
		if (this.dialRef) {
			this.renderer.setStyle(
				this.dialRef.nativeElement,
				'transform',
				`translateY(-50%) rotate(${rotation}deg)`,
			);
		}

		// Dial numbers
		this.numberItems?.forEach((ref, i) => {
			const angle = i * this.angleStep;

			const radius = isRtl ? 'calc(var(--dial-radius, 350px) * -1)' : 'var(--dial-radius, 350px)';

			this.renderer.setStyle(
				ref.nativeElement,
				'transform',
				`rotate(${angle}deg)
			 translateX(${radius})
			 rotate(${-angle}deg)
			 translate(-50%, -50%)
			 rotate(${-rotation}deg)`,
			);
		});

		// Mobile dial: a semicircle standing in for the desktop circular dial
		// (see `.services-mobile-dial`), positioned with plain x/y trig rather
		// than reusing the transform chain above — that one only reads as
		// "upright numbers" on desktop because just a thin off-screen sliver
		// of the circle is ever visible; showing the whole thing centered here
		// would expose the same numbers tilting (and flipping upside down on
		// the far side) as they swing round. Each number sits on a circle
		// whose bottom-most point is the anchor (`bottom: 0` in CSS): the
		// active number (delta 0) sits right at that point, and neighbors
		// swing up and out to the sides as `|delta|` grows — same continuous
		// `rawIndex` driving everything else here, just laid out as a dome.
		const mobileAngleStepRad = (this.mobileDialAngleStep * Math.PI) / 180;

		this.mobileNumberItems?.forEach((ref, i) => {
			const el = ref.nativeElement;
			const delta = i - rawIndex;
			const theta = delta * mobileAngleStepRad;
			const x = this.mobileDialRadius * Math.sin(theta);
			const y = this.mobileDialRadius * (Math.cos(theta) - 1);

			this.renderer.setStyle(el, 'transform', `translate(calc(-50% + ${x}px), ${y}px)`);
		});

		// Content stack: every service's text block sits stacked in the same
		// spot (absolute, inset 0). On mobile it crossfades via opacity/scale
		// exactly like the image stack below. On desktop it instead slides
		// along the column — each block eases up from below into the active
		// spot and keeps drifting up as it fades out — a continuous,
		// scroll-scrubbed version of this section's old "fade up" reveal.
		const contentItems = this.contentItemRefs?.toArray() ?? [];

		contentItems.forEach((ref, i) => {
			const el = ref.nativeElement;

			const signedDistance = i - rawIndex;
			const rawDistance = Math.abs(signedDistance);
			const focus = imageFocus(rawDistance, this.imagePlateau);

			this.renderer.setStyle(el, 'opacity', `${focus}`);

			if (this.isDesktopContent) {
				const translateY = signedDistance * this.contentSlideDistance;

				this.renderer.setStyle(el, 'transform', `translateY(${translateY}vh)`);
			} else {
				const scale = this.contentMinScale + focus * (1 - this.contentMinScale);

				this.renderer.setStyle(el, 'transform', `scale(${scale})`);
			}

			this.renderer.setStyle(el, 'z-index', `${Math.round(focus * 100)}`);

			// Keep off-stage items out of the tab order / click target so a
			// nearly-invisible CTA link a slot away can't be focused or
			// clicked while it's still animating in or out.
			const isActive = i === index;
			this.renderer.setStyle(el, 'pointer-events', isActive ? 'auto' : 'none');
			this.renderer.setAttribute(el, 'aria-hidden', isActive ? 'false' : 'true');
		});

		// Image stack: every service's image sits stacked in the same spot
		// (absolute, inset 0) instead of the old clip-path wipe. As rawIndex
		// scrubs past an image its scale/opacity ease up towards the active
		// state; the outgoing image eases back down the same curve, so the
		// crossfade tracks scroll continuously rather than snapping. The image
		// holds at full scale/opacity through a plateau around its center point
		// instead of starting to fade the instant scroll moves past it — only
		// the outer edge of each segment is spent blending into the next image.
		// `imageFocus` uses a symmetric easing curve so that, for any two
		// neighboring images, their opacities always add up to exactly 1 —
		// otherwise both would render heavily opaque at once mid-crossfade,
		// producing a ghosted double-exposure instead of a clean blend.
		const imageItems = this.imageItemRefs?.toArray() ?? [];

		imageItems.forEach((ref, i) => {
			const el = ref.nativeElement;

			const rawDistance = Math.abs(rawIndex - i);
			const focus = imageFocus(rawDistance, this.imagePlateau);
			const scale = this.imageMinScale + focus * (1 - this.imageMinScale);

			this.renderer.setStyle(el, 'opacity', `${focus}`);
			this.renderer.setStyle(el, 'transform', `translate(-50%, -50%) scale(${scale})`);
			// Stack order tracks visibility continuously (rather than flipping
			// in one step at the halfway point) so that whichever image is
			// swapping to the front does so exactly when both are blended
			// 50/50 — the only point where a stacking-order swap is invisible.
			this.renderer.setStyle(el, 'z-index', `${Math.round(focus * 100)}`);
			this.renderer.setStyle(el, 'pointer-events', i === index ? 'auto' : 'none');
		});

		if (this.activeIndex() !== index) {
			this.ngZone.run(() => this.activeIndex.set(index));
		}
	}
}

function clamp(value: number, min: number, max: number): number {
	return Math.min(Math.max(value, min), max);
}

/**
 * Symmetric ease: smoothStep(1 - t) === 1 - smoothStep(t) for every t. That
 * property is what keeps a crossfade clean — as long as both images in a
 * transition read this same curve from mirrored inputs, their opacities are
 * guaranteed to add up to exactly 1 with no double-exposure zone.
 */
function smoothStep(t: number): number {
	const c = clamp(t, 0, 1);

	return c * c * (3 - 2 * c);
}

/**
 * Opacity/scale focus for one image, given its distance from the current
 * scroll position and the plateau width each image holds at full focus
 * before starting to hand off to its neighbor. Built from `smoothStep` so
 * that two neighboring images always sum to 1 across the handoff, instead of
 * both being independently eased toward full opacity at the same time.
 */
function imageFocus(distance: number, plateau: number): number {
	if (distance <= plateau) {
		return 1;
	}

	const fadeRange = 1 - 2 * plateau;

	if (fadeRange <= 0 || distance >= 1 - plateau) {
		return 0;
	}

	return 1 - smoothStep((distance - plateau) / fadeRange);
}
